const RADIOLOGY_BANK=[{"id":1,"concept":"Radiation Physics","stem":"Which type of radiation is used to create dental radiographs?","choices":["Particulate radiation","Electromagnetic x-radiation","Ultrasound waves","Visible light"],"answer":1,"why":"Dental x-rays are high-energy electromagnetic radiation capable of penetrating tissues.","zh":"牙科X线属于高能电磁辐射，可穿透组织。","rationales":[{"en":"Particulate radiation consists of material particles such as alpha or beta particles, not diagnostic dental x-rays.","zh":"粒子辐射由α或β等粒子组成，不是牙科诊断X线。"},{"en":"Dental x-rays are high-energy electromagnetic radiation capable of penetrating tissues.","zh":"牙科X线属于高能电磁辐射，可穿透组织。"},{"en":"Ultrasound uses mechanical sound waves and is not dental radiography.","zh":"超声使用机械声波，不属于牙科放射成像。"},{"en":"Visible light lacks the energy and penetration needed for radiography.","zh":"可见光能量和穿透力不足，不能用于放射成像。"}],"level":"Board-style","pearl":"Dental x-rays are high-energy electromagnetic radiation capable of penetrating tissues."},{"id":2,"concept":"Radiation Physics","stem":"Ionization occurs when an atom:","choices":["Gains or loses an electron and becomes charged","Splits into two identical atoms","Absorbs only visible light","Loses all protons"],"answer":0,"why":"Ionization is the gain or loss of electrons, producing a charged ion.","zh":"电离是原子获得或失去电子而形成带电离子。","rationales":[{"en":"Ionization is the gain or loss of electrons, producing a charged ion.","zh":"电离是原子获得或失去电子而形成带电离子。"},{"en":"Splitting an atom is nuclear fission, not ordinary ionization.","zh":"原子分裂属于核裂变，不是普通电离。"},{"en":"Visible light usually lacks enough energy to ionize atoms.","zh":"可见光通常能量不足以电离原子。"},{"en":"Loss of protons would alter the element and is not the definition of ionization.","zh":"失去质子会改变元素，并非电离定义。"}],"level":"Board-style","pearl":"Ionization is the gain or loss of electrons, producing a charged ion."},{"id":3,"concept":"Radiation Physics","stem":"Which property primarily determines the penetrating power of an x-ray beam?","choices":["Wavelength and energy","Film packet colour","Patient age only","Room lighting"],"answer":0,"why":"Shorter wavelength and higher energy increase penetration.","zh":"波长越短、能量越高，穿透力越强。","rationales":[{"en":"Shorter wavelength and higher energy increase penetration.","zh":"波长越短、能量越高，穿透力越强。"},{"en":"Packet colour does not alter beam energy.","zh":"胶片包装颜色不影响射线能量。"},{"en":"Patient age may affect selection but does not determine beam penetration.","zh":"患者年龄会影响选择，但不决定射线穿透力。"},{"en":"Room lighting does not control x-ray energy.","zh":"室内光线不控制X线能量。"}],"level":"Clinical","pearl":"Shorter wavelength and higher energy increase penetration."},{"id":4,"concept":"Radiation Safety","stem":"The ALARA principle means exposure should be:","choices":["As low as reasonably achievable","As long as radiographs are available","Adjusted only after an error","Avoided in every patient"],"answer":0,"why":"ALARA requires minimizing radiation while still obtaining diagnostically useful images.","zh":"ALARA要求在获得诊断性影像的同时，将辐射降至合理可达到的最低水平。","rationales":[{"en":"ALARA requires minimizing radiation while still obtaining diagnostically useful images.","zh":"ALARA要求在获得诊断性影像的同时，将辐射降至合理可达到的最低水平。"},{"en":"ALARA concerns dose reduction, not image availability.","zh":"ALARA关注剂量降低，而不是影像数量。"},{"en":"Dose optimization should occur before exposure, not only after errors.","zh":"剂量优化应在曝光前进行，而非出错后。"},{"en":"Appropriately selected radiographs remain clinically justified.","zh":"经合理选择的放射检查仍有临床必要性。"}],"level":"Board-style","pearl":"ALARA requires minimizing radiation while still obtaining diagnostically useful images."},{"id":5,"concept":"Radiation Safety","stem":"Which action most effectively reduces unnecessary patient exposure?","choices":["Use the fastest image receptor compatible with diagnosis","Repeat every unclear image automatically","Increase exposure time for all adults","Take a full-mouth series at every recall"],"answer":0,"why":"Fast receptors reduce the exposure needed to produce a diagnostic image.","zh":"高感光速度的影像接收器可减少获得诊断影像所需的曝光。","rationales":[{"en":"Fast receptors reduce the exposure needed to produce a diagnostic image.","zh":"高感光速度的影像接收器可减少获得诊断影像所需的曝光。"},{"en":"Automatic repeats increase dose and should be avoided unless diagnostically necessary.","zh":"自动重拍会增加剂量，应仅在诊断必需时进行。"},{"en":"Exposure should be individualized, not increased for all adults.","zh":"曝光应个体化，而非所有成人统一增加。"},{"en":"Radiographs must be selected according to need, not routine habit.","zh":"放射检查应按需选择，而非固定常规。"}],"level":"Board-style","pearl":"Fast receptors reduce the exposure needed to produce a diagnostic image."},{"id":6,"concept":"Radiation Safety","stem":"The operator should stand during exposure:","choices":["At least 2 m away and 90–135° from the primary beam","Directly behind the patient","In the path of the central ray","Beside the tube head holding it"],"answer":0,"why":"Distance and position outside the primary beam reduce occupational exposure.","zh":"保持距离并避开主射线方向可降低职业暴露。","rationales":[{"en":"Distance and position outside the primary beam reduce occupational exposure.","zh":"保持距离并避开主射线方向可降低职业暴露。"},{"en":"Standing directly behind the patient may place the operator in scatter radiation.","zh":"直接站在患者后方可能暴露于散射线。"},{"en":"The operator must never stand in the primary beam.","zh":"操作者绝不能站在主射线内。"},{"en":"The tube head should not be hand-held during exposure.","zh":"曝光时不应手持管头。"}],"level":"Clinical","pearl":"Distance and position outside the primary beam reduce occupational exposure."},{"id":7,"concept":"Radiation Biology","stem":"Which cells are generally most radiosensitive?","choices":["Rapidly dividing, immature cells","Mature nerve cells","Fully differentiated muscle cells","Keratinized enamel cells"],"answer":0,"why":"Rapidly dividing and less differentiated cells are most radiosensitive.","zh":"快速分裂、分化程度低的细胞对辐射最敏感。","rationales":[{"en":"Rapidly dividing and less differentiated cells are most radiosensitive.","zh":"快速分裂、分化程度低的细胞对辐射最敏感。"},{"en":"Mature nerve cells divide slowly and are relatively radioresistant.","zh":"成熟神经细胞分裂缓慢，相对耐辐射。"},{"en":"Mature muscle cells are less radiosensitive than rapidly dividing tissues.","zh":"成熟肌细胞较快速分裂组织不敏感。"},{"en":"Enamel is not composed of living keratinized cells.","zh":"牙釉质并非由活的角化细胞组成。"}],"level":"Board-style","pearl":"Rapidly dividing and less differentiated cells are most radiosensitive."},{"id":8,"concept":"Radiation Biology","stem":"A somatic radiation effect occurs in:","choices":["The exposed individual","Future generations only","The x-ray machine","The image receptor"],"answer":0,"why":"Somatic effects occur in the exposed person, whereas genetic effects involve reproductive cells.","zh":"躯体效应发生在受照个体，遗传效应涉及生殖细胞。","rationales":[{"en":"Somatic effects occur in the exposed person, whereas genetic effects involve reproductive cells.","zh":"躯体效应发生在受照个体，遗传效应涉及生殖细胞。"},{"en":"Effects in future generations are genetic, not somatic.","zh":"发生于后代的是遗传效应，不是躯体效应。"},{"en":"Machines do not experience biological somatic effects.","zh":"机器不会产生生物学躯体效应。"},{"en":"Image receptors record radiation but do not have biological effects.","zh":"影像接收器记录辐射，但不会产生生物效应。"}],"level":"Board-style","pearl":"Somatic effects occur in the exposed person, whereas genetic effects involve reproductive cells."},{"id":9,"concept":"Image Quality","stem":"Increasing kVp primarily produces an image with:","choices":["Higher contrast and fewer gray shades","Lower contrast and more gray shades","No change in penetration","More geometric distortion only"],"answer":1,"why":"Higher kVp increases penetration and produces a longer scale of contrast with more gray shades.","zh":"提高kVp会增加穿透力，并产生更多灰阶的长灰阶对比。","rationales":[{"en":"Lower kVp, not higher kVp, tends to create higher contrast.","zh":"较低kVp而非较高kVp通常产生较高对比度。"},{"en":"Higher kVp increases penetration and produces a longer scale of contrast with more gray shades.","zh":"提高kVp会增加穿透力，并产生更多灰阶的长灰阶对比。"},{"en":"kVp directly affects beam energy and penetration.","zh":"kVp直接影响射线能量和穿透力。"},{"en":"Geometric distortion is mainly affected by alignment and distances, not kVp alone.","zh":"几何失真主要受对准和距离影响，而非单独由kVp决定。"}],"level":"Clinical","pearl":"Higher kVp increases penetration and produces a longer scale of contrast with more gray shades."},{"id":10,"concept":"Image Quality","stem":"Increasing mA while all other factors remain constant will primarily:","choices":["Increase image density","Decrease image density","Cause foreshortening","Reduce magnification"],"answer":0,"why":"mA controls the number of x-ray photons and therefore image density.","zh":"mA控制X线光子数量，因此主要影响影像密度。","rationales":[{"en":"mA controls the number of x-ray photons and therefore image density.","zh":"mA控制X线光子数量，因此主要影响影像密度。"},{"en":"Lower mA would decrease density; increasing mA increases it.","zh":"降低mA会降低密度，提高mA则增加密度。"},{"en":"Foreshortening is caused by incorrect vertical angulation.","zh":"缩短是由垂直角度错误造成。"},{"en":"Magnification is controlled by object-receptor and source-object distances.","zh":"放大主要由物体-接收器和焦点-物体距离决定。"}],"level":"Board-style","pearl":"mA controls the number of x-ray photons and therefore image density."},{"id":11,"concept":"Image Quality","stem":"A radiograph appears too light overall. Which error is most likely?","choices":["Insufficient exposure","Excessive exposure","Excessive horizontal angulation","Receptor placed too far occlusally"],"answer":0,"why":"Insufficient exposure produces an image that is too light.","zh":"曝光不足会使影像整体过浅。","rationales":[{"en":"Insufficient exposure produces an image that is too light.","zh":"曝光不足会使影像整体过浅。"},{"en":"Excessive exposure makes the image too dark.","zh":"曝光过量会使影像过暗。"},{"en":"Horizontal angulation mainly affects overlap.","zh":"水平角度主要影响邻接面重叠。"},{"en":"Receptor placement affects coverage, not overall density.","zh":"接收器位置影响覆盖范围，而非整体密度。"}],"level":"Board-style","pearl":"Insufficient exposure produces an image that is too light."},{"id":12,"concept":"Image Quality","stem":"A radiograph appears too dark overall. The most likely cause is:","choices":["Underexposure","Overexposure","Cone-cutting","Incorrect horizontal angulation"],"answer":1,"why":"Overexposure increases density and produces an excessively dark image.","zh":"曝光过量增加密度，使影像过暗。","rationales":[{"en":"Underexposure produces a light image.","zh":"曝光不足会产生过浅影像。"},{"en":"Overexposure increases density and produces an excessively dark image.","zh":"曝光过量增加密度，使影像过暗。"},{"en":"Cone-cutting produces an unexposed clear area, not uniform darkness.","zh":"锥切会形成未曝光的透明区域，而非整体过暗。"},{"en":"Horizontal angulation causes overlap rather than uniform darkness.","zh":"水平角度错误会造成重叠，而非整体过暗。"}],"level":"Clinical","pearl":"Overexposure increases density and produces an excessively dark image."},{"id":13,"concept":"Technique Errors","stem":"Overlapped interproximal contacts are caused primarily by incorrect:","choices":["Horizontal angulation","Vertical angulation","Exposure time","Receptor speed"],"answer":0,"why":"Incorrect horizontal angulation directs the beam through contacts at the wrong angle, causing overlap.","zh":"水平角度错误使射线未通过邻接面间隙，导致重叠。","rationales":[{"en":"Incorrect horizontal angulation directs the beam through contacts at the wrong angle, causing overlap.","zh":"水平角度错误使射线未通过邻接面间隙，导致重叠。"},{"en":"Vertical angulation mainly affects elongation or foreshortening.","zh":"垂直角度主要影响拉长或缩短。"},{"en":"Exposure time affects density, not contact overlap.","zh":"曝光时间影响密度，不影响邻接面重叠。"},{"en":"Receptor speed affects dose, not contact opening.","zh":"接收器速度影响剂量，不影响邻接面开放。"}],"level":"Board-style","pearl":"Incorrect horizontal angulation directs the beam through contacts at the wrong angle, causing overlap."},{"id":14,"concept":"Technique Errors","stem":"Foreshortening results when the vertical angulation is:","choices":["Too steep","Too shallow","Perfectly perpendicular","Unrelated to the tooth"],"answer":0,"why":"Excessive vertical angulation shortens the image.","zh":"垂直角度过大（过陡）会导致影像缩短。","rationales":[{"en":"Excessive vertical angulation shortens the image.","zh":"垂直角度过大（过陡）会导致影像缩短。"},{"en":"Insufficient vertical angulation causes elongation.","zh":"垂直角度不足会导致影像拉长。"},{"en":"Correct perpendicular geometry minimizes distortion.","zh":"正确垂直几何关系可减少失真。"},{"en":"Vertical angulation must be related to the tooth and receptor.","zh":"垂直角度必须与牙齿及接收器相关。"}],"level":"Board-style","pearl":"Excessive vertical angulation shortens the image."},{"id":15,"concept":"Technique Errors","stem":"Elongation results when the vertical angulation is:","choices":["Too steep","Too shallow","Too high in mA","Too short in exposure time"],"answer":1,"why":"Insufficient vertical angulation causes the image to appear elongated.","zh":"垂直角度过小会使影像拉长。","rationales":[{"en":"Too much vertical angulation causes foreshortening.","zh":"垂直角度过大会导致缩短。"},{"en":"Insufficient vertical angulation causes the image to appear elongated.","zh":"垂直角度过小会使影像拉长。"},{"en":"mA affects density, not geometric length.","zh":"mA影响密度，不影响几何长度。"},{"en":"Exposure time affects density, not elongation.","zh":"曝光时间影响密度，不会造成拉长。"}],"level":"Clinical","pearl":"Insufficient vertical angulation causes the image to appear elongated."},{"id":16,"concept":"Technique Errors","stem":"A cone-cut appears as:","choices":["A clear unexposed area with a curved border","Generalized darkening","Overlapped contacts","A double image"],"answer":0,"why":"Cone-cutting occurs when the beam is not centered over the receptor, leaving an unexposed clear area.","zh":"锥切发生于射线未对准接收器，形成未曝光的透明区域。","rationales":[{"en":"Cone-cutting occurs when the beam is not centered over the receptor, leaving an unexposed clear area.","zh":"锥切发生于射线未对准接收器，形成未曝光的透明区域。"},{"en":"General darkening indicates overexposure or processing error.","zh":"整体过暗提示曝光过量或处理错误。"},{"en":"Overlap results from horizontal angulation error.","zh":"重叠来自水平角度错误。"},{"en":"Double images occur from movement or multiple exposure, not cone-cutting.","zh":"双影由移动或重复曝光造成，不是锥切。"}],"level":"Board-style","pearl":"Cone-cutting occurs when the beam is not centered over the receptor, leaving an unexposed clear area."},{"id":17,"concept":"Technique Errors","stem":"The best correction for a blurred radiograph caused by movement is to:","choices":["Stabilize the patient, receptor, and tube head","Increase kVp only","Change horizontal angulation","Place the receptor farther from the tooth"],"answer":0,"why":"Motion blur is prevented by keeping all components still during exposure.","zh":"移动模糊应通过在曝光期间稳定患者、接收器和管头来预防。","rationales":[{"en":"Motion blur is prevented by keeping all components still during exposure.","zh":"移动模糊应通过在曝光期间稳定患者、接收器和管头来预防。"},{"en":"Increasing kVp does not correct movement.","zh":"提高kVp不能纠正移动。"},{"en":"Horizontal angulation corrects overlap, not motion blur.","zh":"水平角度用于纠正重叠，不纠正移动模糊。"},{"en":"Increasing object-receptor distance may increase magnification.","zh":"增加物体-接收器距离可能增加放大。"}],"level":"Board-style","pearl":"Motion blur is prevented by keeping all components still during exposure."},{"id":18,"concept":"Technique Errors","stem":"If apices are missing from a periapical image, the most likely problem is:","choices":["Receptor placement did not extend far enough apically","Excessive exposure","Incorrect horizontal angulation","Patient movement only"],"answer":0,"why":"The receptor must extend beyond the apices to capture the full roots and periapical bone.","zh":"接收器必须超过根尖，才能显示完整牙根和根尖周骨。","rationales":[{"en":"The receptor must extend beyond the apices to capture the full roots and periapical bone.","zh":"接收器必须超过根尖，才能显示完整牙根和根尖周骨。"},{"en":"Exposure changes density, not anatomic coverage.","zh":"曝光改变密度，不改变解剖覆盖。"},{"en":"Horizontal angulation affects contact overlap.","zh":"水平角度影响邻接面重叠。"},{"en":"Movement blurs the image but does not consistently crop all apices.","zh":"移动会使影像模糊，但不会规律性切掉所有根尖。"}],"level":"Clinical","pearl":"The receptor must extend beyond the apices to capture the full roots and periapical bone."},{"id":19,"concept":"Image Selection","stem":"Which image is best for detecting interproximal caries and evaluating crestal bone levels?","choices":["Bitewing","Periapical","Occlusal","Cephalometric"],"answer":0,"why":"Bitewings show crowns, interproximal surfaces, and alveolar crests clearly.","zh":"咬翼片可清楚显示牙冠、邻接面和牙槽嵴。","rationales":[{"en":"Bitewings show crowns, interproximal surfaces, and alveolar crests clearly.","zh":"咬翼片可清楚显示牙冠、邻接面和牙槽嵴。"},{"en":"Periapicals are best for roots and periapical structures, not primarily interproximal caries.","zh":"根尖片主要用于牙根及根尖周结构，不是邻面龋首选。"},{"en":"Occlusal views cover larger areas but lack fine interproximal detail.","zh":"咬合片覆盖范围较大，但邻接面细节不足。"},{"en":"Cephalometric images are used mainly for orthodontic skeletal analysis.","zh":"头影测量片主要用于正畸骨骼分析。"}],"level":"Board-style","pearl":"Bitewings show crowns, interproximal surfaces, and alveolar crests clearly."},{"id":20,"concept":"Image Selection","stem":"Which image best shows the entire tooth from crown to apex and surrounding periapical bone?","choices":["Periapical","Bitewing","Panoramic only","Occlusal"],"answer":0,"why":"A periapical image is designed to show the whole tooth and periapical region.","zh":"根尖片用于显示整颗牙及根尖周区域。","rationales":[{"en":"A periapical image is designed to show the whole tooth and periapical region.","zh":"根尖片用于显示整颗牙及根尖周区域。"},{"en":"Bitewings do not usually include the full roots and apices.","zh":"咬翼片通常不包括完整牙根和根尖。"},{"en":"Panoramic images have less detail for individual teeth.","zh":"全景片对单个牙的细节较少。"},{"en":"Occlusal images survey a broad area rather than one tooth in detail.","zh":"咬合片用于较大范围概览，而非单牙细节。"}],"level":"Board-style","pearl":"A periapical image is designed to show the whole tooth and periapical region."},{"id":21,"concept":"Image Selection","stem":"A healthy 16-year-old reports bilateral posterior jaw pain and possible third-molar eruption. Which image is most appropriate initially?","choices":["Panoramic radiograph","Anterior occlusal radiograph","Single bitewing","Cephalometric radiograph"],"answer":0,"why":"A panoramic image provides broad coverage of both jaws and developing or impacted third molars.","zh":"全景片可广泛显示双侧颌骨及发育中或阻生的第三磨牙。","rationales":[{"en":"A panoramic image provides broad coverage of both jaws and developing or impacted third molars.","zh":"全景片可广泛显示双侧颌骨及发育中或阻生的第三磨牙。"},{"en":"An anterior occlusal view does not show both posterior third-molar regions.","zh":"前牙咬合片不能显示双侧后牙第三磨牙区。"},{"en":"A single bitewing has limited posterior coverage and does not show full third molars.","zh":"单张咬翼片后牙覆盖有限，也不能显示完整第三磨牙。"},{"en":"Cephalometric imaging is mainly for orthodontic relationships.","zh":"头影测量主要用于正畸关系分析。"}],"level":"Clinical","pearl":"A panoramic image provides broad coverage of both jaws and developing or impacted third molars."},{"id":22,"concept":"Image Selection","stem":"Which image is most useful for locating a large salivary stone in the floor of the mouth?","choices":["Mandibular occlusal","Posterior bitewing","Cephalometric","Waters projection"],"answer":0,"why":"A mandibular occlusal image can display the floor of the mouth and radiopaque calculi.","zh":"下颌咬合片可显示口底及不透射线的结石。","rationales":[{"en":"A mandibular occlusal image can display the floor of the mouth and radiopaque calculi.","zh":"下颌咬合片可显示口底及不透射线的结石。"},{"en":"A bitewing does not adequately cover the floor of the mouth.","zh":"咬翼片不能充分显示口底。"},{"en":"Cephalometric images are not designed for salivary stone localization.","zh":"头影测量片不用于唾液腺结石定位。"},{"en":"Waters projection is primarily used for maxillary sinus evaluation.","zh":"Waters位主要用于上颌窦评估。"}],"level":"Board-style","pearl":"A mandibular occlusal image can display the floor of the mouth and radiopaque calculi."},{"id":23,"concept":"Image Selection","stem":"Which projection is commonly used to evaluate the maxillary sinuses?","choices":["Waters projection","Bitewing projection","Mandibular occlusal projection","Submentovertex only"],"answer":0,"why":"The Waters projection provides a useful view of the maxillary sinuses.","zh":"Waters位可良好显示上颌窦。","rationales":[{"en":"The Waters projection provides a useful view of the maxillary sinuses.","zh":"Waters位可良好显示上颌窦。"},{"en":"Bitewings are for teeth and crestal bone, not sinus overview.","zh":"咬翼片用于牙齿和牙槽嵴，不用于上颌窦概览。"},{"en":"Mandibular occlusal images focus on the mandible and floor of mouth.","zh":"下颌咬合片重点显示下颌骨和口底。"},{"en":"Submentovertex is useful for skull-base relationships, not the standard maxillary sinus view.","zh":"颏顶位用于颅底关系，并非标准上颌窦视图。"}],"level":"Board-style","pearl":"The Waters projection provides a useful view of the maxillary sinuses."},{"id":24,"concept":"Image Geometry","stem":"To minimize magnification, the operator should use:","choices":["Long source-to-object distance and short object-to-receptor distance","Short source-to-object distance and long object-to-receptor distance","Long object-to-receptor distance only","Any distance because magnification cannot be controlled"],"answer":0,"why":"A long focal distance and close receptor placement reduce divergence and magnification.","zh":"较长的焦点距离和较短的物体-接收器距离可减少射线发散和放大。","rationales":[{"en":"A long focal distance and close receptor placement reduce divergence and magnification.","zh":"较长的焦点距离和较短的物体-接收器距离可减少射线发散和放大。"},{"en":"This combination increases magnification.","zh":"这种组合会增加放大。"},{"en":"A long object-receptor distance increases magnification.","zh":"较大的物体-接收器距离会增加放大。"},{"en":"Magnification can be controlled by geometric relationships.","zh":"放大可通过几何关系控制。"}],"level":"Clinical","pearl":"A long focal distance and close receptor placement reduce divergence and magnification."},{"id":25,"concept":"Image Geometry","stem":"The paralleling technique requires the receptor to be:","choices":["Parallel to the long axis of the tooth","Perpendicular to the long axis of the tooth","Placed on the occlusal surface only","Angled randomly for comfort"],"answer":0,"why":"In the paralleling technique, the receptor is parallel to the tooth and the beam is perpendicular to both.","zh":"平行技术中，接收器与牙长轴平行，射线垂直于二者。","rationales":[{"en":"In the paralleling technique, the receptor is parallel to the tooth and the beam is perpendicular to both.","zh":"平行技术中，接收器与牙长轴平行，射线垂直于二者。"},{"en":"A receptor perpendicular to the tooth would distort the image.","zh":"接收器与牙长轴垂直会造成失真。"},{"en":"Occlusal placement describes occlusal imaging, not paralleling periapicals.","zh":"放在咬合面上属于咬合片，不是平行根尖片。"},{"en":"Random angulation prevents reproducible diagnostic images.","zh":"随意角度无法获得可重复的诊断影像。"}],"level":"Board-style","pearl":"In the paralleling technique, the receptor is parallel to the tooth and the beam is perpendicular to both."},{"id":26,"concept":"Image Geometry","stem":"The bisecting-angle technique directs the central ray perpendicular to:","choices":["The imaginary bisector between tooth and receptor","The tooth only","The receptor only","The occlusal plane only"],"answer":0,"why":"The central ray is directed perpendicular to the imaginary bisector to reduce distortion.","zh":"射线应垂直于牙齿与接收器夹角的虚拟平分线，以减少失真。","rationales":[{"en":"The central ray is directed perpendicular to the imaginary bisector to reduce distortion.","zh":"射线应垂直于牙齿与接收器夹角的虚拟平分线，以减少失真。"},{"en":"Perpendicular to the tooth alone would not follow the bisecting rule.","zh":"仅垂直于牙齿不符合等角平分法。"},{"en":"Perpendicular to the receptor alone describes paralleling geometry.","zh":"仅垂直于接收器更接近平行技术几何。"},{"en":"The occlusal plane is not the bisecting reference.","zh":"咬合平面不是平分参考线。"}],"level":"Board-style","pearl":"The central ray is directed perpendicular to the imaginary bisector to reduce distortion."},{"id":27,"concept":"Normal Anatomy","stem":"Which structure usually appears radiolucent on a dental radiograph?","choices":["Maxillary sinus","Enamel","Lamina dura","Zygomatic process"],"answer":0,"why":"Air-filled spaces such as the maxillary sinus appear radiolucent.","zh":"含气的上颌窦在影像上呈透射线影。","rationales":[{"en":"Air-filled spaces such as the maxillary sinus appear radiolucent.","zh":"含气的上颌窦在影像上呈透射线影。"},{"en":"Enamel is highly mineralized and radiopaque.","zh":"牙釉质矿化度高，呈不透射线影。"},{"en":"The lamina dura appears as a radiopaque line.","zh":"硬骨板呈不透射线白线。"},{"en":"The zygomatic process is dense bone and appears radiopaque.","zh":"颧突为致密骨，呈不透射线影。"}],"level":"Clinical","pearl":"Air-filled spaces such as the maxillary sinus appear radiolucent."},{"id":28,"concept":"Normal Anatomy","stem":"The lamina dura appears as:","choices":["A thin radiopaque line surrounding the tooth socket","A wide radiolucent band in enamel","A soft-tissue shadow over the crown","A radiolucent sinus cavity"],"answer":0,"why":"The lamina dura is the cortical lining of the alveolus and appears radiopaque.","zh":"硬骨板是牙槽窝的皮质骨内壁，影像上呈不透射线线。","rationales":[{"en":"The lamina dura is the cortical lining of the alveolus and appears radiopaque.","zh":"硬骨板是牙槽窝的皮质骨内壁，影像上呈不透射线线。"},{"en":"Enamel is radiopaque, not a radiolucent band.","zh":"牙釉质呈不透射线影，不是透射线带。"},{"en":"A soft-tissue shadow is not the lamina dura.","zh":"软组织影不是硬骨板。"},{"en":"A sinus cavity is radiolucent and anatomically distinct.","zh":"窦腔呈透射线影，且与硬骨板不同。"}],"level":"Board-style","pearl":"The lamina dura is the cortical lining of the alveolus and appears radiopaque."},{"id":29,"concept":"Normal Anatomy","stem":"The periodontal ligament space normally appears as:","choices":["A thin radiolucent line around the root","A thick radiopaque mass","A radiopaque line within the pulp","A radiolucent area only at the crown"],"answer":0,"why":"The periodontal ligament space is a thin radiolucent line between root and lamina dura.","zh":"牙周膜间隙是在牙根与硬骨板之间的细窄透射线线。","rationales":[{"en":"The periodontal ligament space is a thin radiolucent line between root and lamina dura.","zh":"牙周膜间隙是在牙根与硬骨板之间的细窄透射线线。"},{"en":"A thick radiopaque mass would represent bone or restorative material.","zh":"厚的不透射线团块多代表骨或修复材料。"},{"en":"The pulp is radiolucent and the PDL is not within it.","zh":"牙髓呈透射线影，牙周膜不在牙髓内。"},{"en":"The PDL surrounds the root, not only the crown.","zh":"牙周膜环绕牙根，不只在牙冠。"}],"level":"Board-style","pearl":"The periodontal ligament space is a thin radiolucent line between root and lamina dura."},{"id":30,"concept":"Normal Anatomy","stem":"Which landmark appears as a U- or J-shaped radiopacity above the maxillary first molar region?","choices":["Zygomatic process of the maxilla","Mental foramen","Incisive foramen","Mandibular canal"],"answer":0,"why":"The zygomatic process commonly appears as a U- or J-shaped radiopacity in the maxillary molar region.","zh":"上颌颧突常在上颌磨牙区呈U形或J形不透射线影。","rationales":[{"en":"The zygomatic process commonly appears as a U- or J-shaped radiopacity in the maxillary molar region.","zh":"上颌颧突常在上颌磨牙区呈U形或J形不透射线影。"},{"en":"The mental foramen is a mandibular premolar radiolucency.","zh":"颏孔位于下颌前磨牙区，呈透射线影。"},{"en":"The incisive foramen is in the anterior maxilla.","zh":"切牙孔位于上颌前牙区。"},{"en":"The mandibular canal is a radiolucent band in the mandible.","zh":"下颌管是下颌骨内的透射线带。"}],"level":"Clinical","pearl":"The zygomatic process commonly appears as a U- or J-shaped radiopacity in the maxillary molar region."},{"id":31,"concept":"Interpretation","stem":"Radiographic interpretation should begin with:","choices":["A systematic review of image quality and normal anatomy","Immediate diagnosis of the darkest area","Ignoring clinical findings","Comparing only with internet images"],"answer":0,"why":"A systematic approach starts with image quality, normal anatomy, and correlation with clinical data.","zh":"系统解读应先评估影像质量、正常解剖，并结合临床资料。","rationales":[{"en":"A systematic approach starts with image quality, normal anatomy, and correlation with clinical data.","zh":"系统解读应先评估影像质量、正常解剖，并结合临床资料。"},{"en":"Jumping to the darkest area risks missing normal anatomy and other findings.","zh":"直接关注最暗区域可能误判正常解剖并遗漏其他发现。"},{"en":"Radiographs must be interpreted with clinical findings.","zh":"放射影像必须结合临床发现解读。"},{"en":"Internet comparison cannot replace structured clinical interpretation.","zh":"网络图片比较不能替代系统临床解读。"}],"level":"Board-style","pearl":"A systematic approach starts with image quality, normal anatomy, and correlation with clinical data."},{"id":32,"concept":"Interpretation","stem":"Interproximal caries most commonly appears as:","choices":["A triangular radiolucency below the contact area","A round radiopacity in enamel","A radiopaque line along the PDL","A uniform darkening of the whole image"],"answer":0,"why":"Early interproximal caries typically appears as a triangular radiolucency beneath the contact.","zh":"早期邻面龋常在接触点下方呈三角形透射线影。","rationales":[{"en":"Early interproximal caries typically appears as a triangular radiolucency beneath the contact.","zh":"早期邻面龋常在接触点下方呈三角形透射线影。"},{"en":"Caries is radiolucent, not radiopaque.","zh":"龋损呈透射线影，不是不透射线影。"},{"en":"A PDL line is normal anatomy and not caries.","zh":"牙周膜线属于正常解剖，不是龋损。"},{"en":"Uniform darkening indicates exposure or processing error.","zh":"整体变暗提示曝光或处理错误。"}],"level":"Board-style","pearl":"Early interproximal caries typically appears as a triangular radiolucency beneath the contact."},{"id":33,"concept":"Interpretation","stem":"Horizontal periodontal bone loss is characterized by:","choices":["A relatively even reduction in bone height parallel to the CEJs","An angular defect along one root","An intact alveolar crest at the CEJ","A radiopaque mass in the furcation"],"answer":0,"why":"Horizontal bone loss lowers the crest while maintaining a generally parallel relationship to adjacent CEJs.","zh":"水平骨丧失使牙槽嵴高度降低，但通常仍与相邻釉牙骨质界平行。","rationales":[{"en":"Horizontal bone loss lowers the crest while maintaining a generally parallel relationship to adjacent CEJs.","zh":"水平骨丧失使牙槽嵴高度降低，但通常仍与相邻釉牙骨质界平行。"},{"en":"An angular defect describes vertical bone loss.","zh":"角形缺损属于垂直骨丧失。"},{"en":"An intact crest does not indicate bone loss.","zh":"完整牙槽嵴不表示骨丧失。"},{"en":"A furcation radiopacity is not the pattern of periodontal loss.","zh":"根分叉区不透射线团块不是牙周骨丧失模式。"}],"level":"Clinical","pearl":"Horizontal bone loss lowers the crest while maintaining a generally parallel relationship to adjacent CEJs."},{"id":34,"concept":"Interpretation","stem":"Vertical bone loss is best described as:","choices":["An angular defect that is not parallel to the CEJs","Uniform crestal lowering across several teeth","Increased enamel radiopacity","Widening of the pulp chamber only"],"answer":0,"why":"Vertical bone loss creates an angular or oblique defect adjacent to a tooth.","zh":"垂直骨丧失在牙旁形成角形或斜形缺损。","rationales":[{"en":"Vertical bone loss creates an angular or oblique defect adjacent to a tooth.","zh":"垂直骨丧失在牙旁形成角形或斜形缺损。"},{"en":"Uniform crestal lowering is horizontal bone loss.","zh":"均匀牙槽嵴降低属于水平骨丧失。"},{"en":"Enamel radiopacity does not indicate periodontal bone loss.","zh":"牙釉质不透射线程度与牙周骨丧失无关。"},{"en":"Pulp chamber width is not a periodontal bone-loss pattern.","zh":"牙髓腔宽度不是牙周骨丧失模式。"}],"level":"Board-style","pearl":"Vertical bone loss creates an angular or oblique defect adjacent to a tooth."},{"id":35,"concept":"Interpretation","stem":"A well-defined radiolucency at the apex of a nonvital tooth most strongly suggests:","choices":["Periapical inflammatory disease","Normal mental foramen in every case","Enamel hypoplasia","Cervical burnout"],"answer":0,"why":"A periapical radiolucency associated with a nonvital tooth suggests inflammatory periapical pathology.","zh":"无活力牙根尖处的透射线影提示炎性根尖周病变。","rationales":[{"en":"A periapical radiolucency associated with a nonvital tooth suggests inflammatory periapical pathology.","zh":"无活力牙根尖处的透射线影提示炎性根尖周病变。"},{"en":"The mental foramen may mimic a lesion near premolars, but vitality testing helps distinguish it.","zh":"颏孔可在前磨牙区模拟病变，但牙髓活力测试可鉴别。"},{"en":"Enamel hypoplasia affects crown structure, not the apex.","zh":"牙釉质发育不全影响牙冠，不影响根尖。"},{"en":"Cervical burnout occurs near the CEJ, not the root apex.","zh":"颈部透射伪影位于釉牙骨质界附近，不在根尖。"}],"level":"Board-style","pearl":"A periapical radiolucency associated with a nonvital tooth suggests inflammatory periapical pathology."},{"id":36,"concept":"Interpretation","stem":"Which feature most strongly suggests a benign, slow-growing lesion?","choices":["Well-defined corticated border","Poorly defined moth-eaten border","Rapid destruction of adjacent structures","Irregular invasive margins"],"answer":0,"why":"A well-defined corticated border often indicates slow growth that allowed bone to remodel.","zh":"清楚且皮质化的边界常提示生长缓慢，骨组织有时间重塑。","rationales":[{"en":"A well-defined corticated border often indicates slow growth that allowed bone to remodel.","zh":"清楚且皮质化的边界常提示生长缓慢，骨组织有时间重塑。"},{"en":"A poorly defined moth-eaten border suggests aggressive disease.","zh":"边界不清的虫蚀样影提示侵袭性病变。"},{"en":"Rapid destruction is more concerning for aggressive pathology.","zh":"快速破坏更提示侵袭性病理。"},{"en":"Irregular invasive margins are not typical of benign slow growth.","zh":"不规则浸润性边缘并非良性缓慢生长的典型表现。"}],"level":"Clinical","pearl":"A well-defined corticated border often indicates slow growth that allowed bone to remodel."},{"id":37,"concept":"Interpretation","stem":"Which finding is most concerning for malignancy?","choices":["Ill-defined destructive borders","A stable corticated unilocular radiolucency","Symmetric normal anatomy","A small unchanged radiopacity"],"answer":0,"why":"Malignant lesions often show poorly defined, invasive, destructive borders.","zh":"恶性病变常表现为边界不清、浸润性和破坏性改变。","rationales":[{"en":"Malignant lesions often show poorly defined, invasive, destructive borders.","zh":"恶性病变常表现为边界不清、浸润性和破坏性改变。"},{"en":"A stable corticated unilocular lesion more often suggests benign behavior.","zh":"稳定、皮质化的单房透射线影更常提示良性行为。"},{"en":"Symmetric normal anatomy is not malignant.","zh":"对称正常解剖不是恶性表现。"},{"en":"A small unchanged radiopacity is less concerning than destructive change.","zh":"小且无变化的不透射线影较破坏性改变更少令人担忧。"}],"level":"Board-style","pearl":"Malignant lesions often show poorly defined, invasive, destructive borders."},{"id":38,"concept":"Digital Imaging","stem":"A major advantage of digital radiography is:","choices":["Rapid image display and reduced processing chemicals","Zero radiation exposure","No need for infection control","No possibility of image error"],"answer":0,"why":"Digital systems provide rapid display and eliminate chemical film processing.","zh":"数字系统可快速显示影像，并免除化学胶片处理。","rationales":[{"en":"Digital systems provide rapid display and eliminate chemical film processing.","zh":"数字系统可快速显示影像，并免除化学胶片处理。"},{"en":"Digital imaging still uses ionizing radiation.","zh":"数字成像仍使用电离辐射。"},{"en":"Sensors and equipment still require infection-control measures.","zh":"传感器和设备仍需感染控制。"},{"en":"Positioning and exposure errors can still occur.","zh":"定位和曝光错误仍可能发生。"}],"level":"Board-style","pearl":"Digital systems provide rapid display and eliminate chemical film processing."},{"id":39,"concept":"Digital Imaging","stem":"To reduce cross-contamination with a digital sensor, the clinician should:","choices":["Use an appropriate barrier and disinfect according to manufacturer guidance","Immerse every sensor in sterilant","Reuse a torn barrier","Skip hand hygiene because the sensor is digital"],"answer":0,"why":"Barriers and manufacturer-approved disinfection protect the sensor and prevent contamination.","zh":"使用屏障并按厂家指导消毒可保护传感器并防止污染。","rationales":[{"en":"Barriers and manufacturer-approved disinfection protect the sensor and prevent contamination.","zh":"使用屏障并按厂家指导消毒可保护传感器并防止污染。"},{"en":"Many sensors cannot be immersed and may be damaged.","zh":"许多传感器不能浸泡，否则会损坏。"},{"en":"A torn barrier does not provide effective protection.","zh":"破损屏障不能提供有效保护。"},{"en":"Hand hygiene remains essential with digital equipment.","zh":"使用数字设备时仍必须进行手卫生。"}],"level":"Clinical","pearl":"Barriers and manufacturer-approved disinfection protect the sensor and prevent contamination."},{"id":40,"concept":"Patient Selection","stem":"Radiographs should be prescribed based primarily on:","choices":["Individual clinical findings and risk assessment","A fixed schedule for every patient","The patient’s insurance allowance","The operator’s convenience"],"answer":0,"why":"Selection criteria require individualized assessment of history, examination, and disease risk.","zh":"放射检查应根据病史、检查结果和疾病风险进行个体化选择。","rationales":[{"en":"Selection criteria require individualized assessment of history, examination, and disease risk.","zh":"放射检查应根据病史、检查结果和疾病风险进行个体化选择。"},{"en":"A fixed schedule may expose low-risk patients unnecessarily.","zh":"固定时间表可能使低风险患者接受不必要曝光。"},{"en":"Insurance coverage does not determine clinical need.","zh":"保险额度不能决定临床需要。"},{"en":"Convenience is not a valid justification for radiation.","zh":"方便性不是使用辐射的正当理由。"}],"level":"Board-style","pearl":"Selection criteria require individualized assessment of history, examination, and disease risk."},{"id":41,"concept":"Patient Selection","stem":"For a pregnant patient, necessary dental radiographs should be:","choices":["Taken when clinically justified using appropriate protection and dose reduction","Automatically postponed until after delivery","Taken without any selection criteria","Repeated to ensure perfect images"],"answer":0,"why":"Pregnancy does not prohibit justified dental radiography when proper protection and optimization are used.","zh":"妊娠并非绝对禁忌；若临床必要，应采用适当防护和剂量优化。","rationales":[{"en":"Pregnancy does not prohibit justified dental radiography when proper protection and optimization are used.","zh":"妊娠并非绝对禁忌；若临床必要，应采用适当防护和剂量优化。"},{"en":"Delaying necessary diagnosis may create greater risk.","zh":"推迟必要诊断可能带来更大风险。"},{"en":"Selection criteria remain essential during pregnancy.","zh":"妊娠期间仍必须遵循选择标准。"},{"en":"Unnecessary repeats should be avoided.","zh":"应避免不必要重拍。"}],"level":"Board-style","pearl":"Pregnancy does not prohibit justified dental radiography when proper protection and optimization are used."},{"id":42,"concept":"Patient Selection","stem":"Which factor most increases the need for bitewing radiographs?","choices":["High caries risk and new proximal lesions","No teeth and no symptoms","Recently completed normal images with no risk change","Patient preference alone"],"answer":0,"why":"High caries risk and suspected proximal disease justify bitewing imaging.","zh":"高龋风险及疑似邻面病变可支持拍摄咬翼片。","rationales":[{"en":"High caries risk and suspected proximal disease justify bitewing imaging.","zh":"高龋风险及疑似邻面病变可支持拍摄咬翼片。"},{"en":"An edentulous asymptomatic patient does not need bitewings.","zh":"无牙且无症状患者不需要咬翼片。"},{"en":"Recent diagnostic images and unchanged low risk reduce the need for repeats.","zh":"近期已有诊断影像且风险未变时，应减少重拍。"},{"en":"Patient preference alone is not sufficient clinical justification.","zh":"仅患者偏好不足以构成临床正当性。"}],"level":"Clinical","pearl":"High caries risk and suspected proximal disease justify bitewing imaging."},{"id":43,"concept":"Localization","stem":"The SLOB rule means that when the tube head shifts, the object that moves in the same direction is:","choices":["Lingual","Buccal","Occlusal","Apical"],"answer":0,"why":"SLOB stands for Same Lingual, Opposite Buccal.","zh":"SLOB表示“同向舌侧，反向颊侧”。","rationales":[{"en":"SLOB stands for Same Lingual, Opposite Buccal.","zh":"SLOB表示“同向舌侧，反向颊侧”。"},{"en":"A buccal object moves opposite the tube-head shift.","zh":"颊侧物体会与管头移动方向相反。"},{"en":"Occlusal is not part of the SLOB relationship.","zh":"咬合方向不属于SLOB关系。"},{"en":"Apical describes position along the root, not buccolingual localization.","zh":"根尖方向描述牙根位置，不用于颊舌侧定位。"}],"level":"Board-style","pearl":"SLOB stands for Same Lingual, Opposite Buccal."},{"id":44,"concept":"Panoramic Imaging","stem":"If the patient is positioned too far forward in the panoramic focal trough, the anterior teeth usually appear:","choices":["Narrow and blurred","Wide and magnified","Perfectly sharp","Completely absent"],"answer":0,"why":"Too-far-forward positioning makes anterior teeth narrowed and blurred.","zh":"患者过于前移会使前牙影像变窄且模糊。","rationales":[{"en":"Too-far-forward positioning makes anterior teeth narrowed and blurred.","zh":"患者过于前移会使前牙影像变窄且模糊。"},{"en":"Wide magnified anterior teeth usually occur when the patient is too far back.","zh":"前牙变宽放大通常见于患者位置过后。"},{"en":"Incorrect positioning reduces sharpness.","zh":"位置错误会降低清晰度。"},{"en":"The teeth usually remain visible but distorted.","zh":"牙齿通常仍可见，但会失真。"}],"level":"Board-style","pearl":"Too-far-forward positioning makes anterior teeth narrowed and blurred."},{"id":45,"concept":"Panoramic Imaging","stem":"If the patient is positioned too far back in the panoramic focal trough, the anterior teeth usually appear:","choices":["Narrow and blurred","Wide and magnified","Foreshortened only","Unchanged"],"answer":1,"why":"Too-far-back positioning makes anterior teeth widened and magnified.","zh":"患者过于后移会使前牙影像变宽并放大。","rationales":[{"en":"Narrow blurred anterior teeth occur when the patient is too far forward.","zh":"前牙变窄模糊通常见于患者过于前移。"},{"en":"Too-far-back positioning makes anterior teeth widened and magnified.","zh":"患者过于后移会使前牙影像变宽并放大。"},{"en":"The main effect is widening and magnification, not only foreshortening.","zh":"主要表现是变宽和放大，而非仅缩短。"},{"en":"Positioning errors clearly alter the panoramic image.","zh":"位置错误会明显改变全景影像。"}],"level":"Clinical","pearl":"Too-far-back positioning makes anterior teeth widened and magnified."},{"id":46,"concept":"Panoramic Imaging","stem":"A ghost image on a panoramic radiograph is typically:","choices":["Magnified, blurred, and located higher on the opposite side","Sharp and located on the same side","Always radiolucent","Produced only by patient movement"],"answer":0,"why":"Ghost images appear magnified, blurred, higher, and on the contralateral side.","zh":"鬼影通常放大、模糊、位置更高，并出现在对侧。","rationales":[{"en":"Ghost images appear magnified, blurred, higher, and on the contralateral side.","zh":"鬼影通常放大、模糊、位置更高，并出现在对侧。"},{"en":"Real images are generally on the same side and less distorted.","zh":"真实影像通常位于同侧且失真较少。"},{"en":"Ghost images may be radiopaque depending on the object.","zh":"鬼影可因物体性质而呈不透射线影。"},{"en":"Ghost images arise from panoramic geometry, not only movement.","zh":"鬼影源于全景几何原理，不仅由移动造成。"}],"level":"Board-style","pearl":"Ghost images appear magnified, blurred, higher, and on the contralateral side."},{"id":47,"concept":"Quality Assurance","stem":"A quality-assurance program should include:","choices":["Monitoring equipment, processing, image quality, and repeat rates","Deleting all rejected images without review","Using the same exposure for every patient","Ignoring minor errors"],"answer":0,"why":"Quality assurance systematically monitors the entire imaging process to reduce errors and dose.","zh":"质量保证应系统监测设备、处理、影像质量和重拍率，以减少错误和剂量。","rationales":[{"en":"Quality assurance systematically monitors the entire imaging process to reduce errors and dose.","zh":"质量保证应系统监测设备、处理、影像质量和重拍率，以减少错误和剂量。"},{"en":"Rejected images should be analyzed to identify causes and prevent recurrence.","zh":"废片应分析原因以防重复发生，而非直接删除。"},{"en":"Exposure must be adjusted to patient and receptor factors.","zh":"曝光应根据患者和接收器因素调整。"},{"en":"Minor errors can reveal trends and should not be ignored.","zh":"小错误也可反映趋势，不应忽视。"}],"level":"Board-style","pearl":"Quality assurance systematically monitors the entire imaging process to reduce errors and dose."},{"id":48,"concept":"Quality Assurance","stem":"A high repeat rate most directly indicates a need to:","choices":["Review technique and identify recurring causes","Increase exposure for every patient","Discard the quality-assurance log","Stop using positioning devices"],"answer":0,"why":"Repeat analysis identifies patterns such as positioning, movement, or exposure errors.","zh":"分析重拍可发现定位、移动或曝光等重复性错误模式。","rationales":[{"en":"Repeat analysis identifies patterns such as positioning, movement, or exposure errors.","zh":"分析重拍可发现定位、移动或曝光等重复性错误模式。"},{"en":"Increasing exposure indiscriminately may worsen dose without solving technique errors.","zh":"统一增加曝光会增加剂量，未必解决技术问题。"},{"en":"The log is needed to track and improve performance.","zh":"质量记录用于追踪和改进，不能丢弃。"},{"en":"Positioning devices usually improve reproducibility.","zh":"定位器通常可提高可重复性。"}],"level":"Clinical","pearl":"Repeat analysis identifies patterns such as positioning, movement, or exposure errors."},{"id":49,"concept":"Documentation","stem":"Radiographic records should include:","choices":["Date, type of image, findings, and relevant interpretation","Only the patient name","Only the exposure settings","No documentation if images look normal"],"answer":0,"why":"Complete documentation supports continuity of care, legal records, and appropriate follow-up.","zh":"完整记录有助于连续护理、法律文件和后续随访。","rationales":[{"en":"Complete documentation supports continuity of care, legal records, and appropriate follow-up.","zh":"完整记录有助于连续护理、法律文件和后续随访。"},{"en":"A name alone does not document the examination.","zh":"仅有姓名不能记录检查内容。"},{"en":"Exposure settings alone omit diagnostic information.","zh":"仅记录曝光参数会遗漏诊断信息。"},{"en":"Normal findings should still be documented.","zh":"即使正常也应记录检查结果。"}],"level":"Board-style","pearl":"Complete documentation supports continuity of care, legal records, and appropriate follow-up."},{"id":50,"concept":"Technique Errors","stem":"A periapical image shows the crowns and roots appearing too long. Which correction is MOST appropriate?","choices":["Increase vertical angulation","Decrease vertical angulation","Increase horizontal angulation","Move the receptor farther from the teeth"],"answer":0,"why":"Elongation usually results from insufficient vertical angulation; increasing the vertical angulation corrects the image.","zh":"根尖片中牙冠和牙根显得过长。最适当的纠正方法是什么？","rationales":[{"en":"Correct: insufficient vertical angulation causes elongation, so the angle should be increased.","zh":"正确：垂直角度不足会导致影像拉长，因此应增加垂直角度。"},{"en":"Decreasing the vertical angle would worsen elongation.","zh":"减小垂直角度会使影像拉长更加明显。"},{"en":"Horizontal angulation mainly affects overlap of proximal contacts.","zh":"水平角度主要影响邻接面重叠。"},{"en":"Increasing receptor-tooth distance increases magnification and unsharpness rather than correcting elongation.","zh":"增加感受器与牙齿的距离会增加放大和模糊，而不能纠正拉长。"}],"level":"Clinical","pearl":"Elongation means vertical angulation is too low; foreshortening means it is too steep."},{"id":51,"concept":"Technique Errors","stem":"A bitewing image shows severe overlap of the interproximal contacts. What is the MOST likely cause?","choices":["Incorrect horizontal angulation","Excessive vertical angulation","Insufficient exposure time","Patient movement"],"answer":0,"why":"Overlapped contacts are caused primarily by incorrect horizontal angulation.","zh":"咬翼片中邻接面严重重叠。最可能的原因是什么？","rationales":[{"en":"Correct: the central ray was not directed through the interproximal contacts.","zh":"正确：中央射线未通过邻接面。"},{"en":"Vertical angulation affects distortion and crestal bone projection more than contact overlap.","zh":"垂直角度主要影响影像变形和牙槽嵴显示，而不是邻接面重叠。"},{"en":"Insufficient exposure produces a light image, not overlapped contacts.","zh":"曝光不足会使影像过浅，而不会造成邻接面重叠。"},{"en":"Movement causes generalized blur rather than selective interproximal overlap.","zh":"患者移动会造成整体模糊，而不是特定的邻接面重叠。"}],"level":"Board-style","pearl":"Overlap points to horizontal-angulation error."},{"id":52,"concept":"Technique Errors","stem":"Only part of the receptor was exposed, leaving a sharply defined clear semicircular area. Which error occurred?","choices":["Cone cut","Double exposure","Static electricity","Reversed receptor"],"answer":0,"why":"A cone cut occurs when the x-ray beam is not centred over the receptor.","zh":"感受器只有部分被曝光，并出现边界清晰的半圆形透明区。发生了哪种错误？","rationales":[{"en":"Correct: a cone cut results from misalignment between the PID and receptor.","zh":"正确：锥切是由于指示筒与感受器未对准。"},{"en":"Double exposure creates two superimposed images.","zh":"双重曝光会产生两个重叠影像。"},{"en":"Static electricity produces branching black lines or marks.","zh":"静电通常会产生树枝状黑线或斑点。"},{"en":"A reversed receptor commonly produces a herringbone or tire-track pattern.","zh":"感受器反放通常会出现人字形或轮胎纹样影像。"}],"level":"Clinical","pearl":"A sharply defined unexposed area usually indicates cone cut."},{"id":53,"concept":"Image Selection","stem":"A patient has generalized severe periodontal disease with suspected vertical bone loss. Which image set is MOST useful for assessing the extent of alveolar bone loss?","choices":["Vertical bitewings with selected periapicals","Anterior occlusal images only","A single panoramic image only","No radiographs are needed"],"answer":0,"why":"Vertical bitewings show crestal bone over a greater root length, and selected periapicals add detail where needed.","zh":"患者有广泛严重牙周病并疑有垂直型骨丧失。哪组影像最有助于评估牙槽骨丧失范围？","rationales":[{"en":"Correct: vertical bitewings are especially useful when bone loss is advanced, with periapicals supplementing detail.","zh":"正确：当骨丧失较严重时，垂直咬翼片特别有用，根尖片可补充细节。"},{"en":"Occlusal images do not adequately show generalized crestal bone levels.","zh":"咬合片不能充分显示广泛的牙槽嵴骨水平。"},{"en":"A panoramic image can provide an overview but lacks the detail needed for precise periodontal assessment.","zh":"全景片可提供概览，但缺乏精确牙周评估所需的细节。"},{"en":"Radiographs are indicated when findings suggest significant periodontal destruction.","zh":"当临床表现提示显著牙周破坏时，应进行影像检查。"}],"level":"Clinical","pearl":"Advanced periodontal bone loss often calls for vertical bitewings plus selected periapicals."},{"id":54,"concept":"Panoramic Errors","stem":"On a panoramic image, the anterior teeth appear narrow and blurred, and the cervical spine is projected over the anterior region. What positioning error is MOST likely?","choices":["The patient was positioned too far forward","The patient was positioned too far back","The chin was tipped too high","The tongue was held against the palate"],"answer":0,"why":"Positioning too far forward causes the anterior teeth to appear narrowed and blurred.","zh":"全景片中前牙显得狭窄且模糊，并且颈椎影像投射到前牙区。最可能的定位错误是什么？","rationales":[{"en":"Correct: being too far forward places the anterior teeth outside the focal trough and makes them narrow.","zh":"正确：患者过于靠前会使前牙离开焦点层并显得狭窄。"},{"en":"Being too far back typically makes anterior teeth appear widened.","zh":"患者过于靠后通常会使前牙显得加宽。"},{"en":"A chin tipped too high produces a flat or reverse smile line and may superimpose the hard palate.","zh":"下巴过高会产生平直或反向微笑线，并可能使硬腭重叠。"},{"en":"Failure to place the tongue on the palate creates a radiolucent palatoglossal air space.","zh":"舌头未贴腭会形成透射性的腭舌气隙。"}],"level":"Clinical","pearl":"Too far forward equals narrow anterior teeth; too far back equals wide anterior teeth."},{"id":55,"concept":"Panoramic Errors","stem":"A panoramic image displays a broad radiolucent band over the maxillary apices. Which instruction was MOST likely not followed?","choices":["Keep the tongue against the palate","Bite in the groove","Hold the handles firmly","Remove eyeglasses"],"answer":0,"why":"A palatoglossal air space appears when the tongue is not held against the palate.","zh":"全景片上颌根尖区出现宽大的透射带。患者最可能未遵循哪项指示？","rationales":[{"en":"Correct: failure to keep the tongue against the palate creates the dark palatoglossal air space.","zh":"正确：舌头未贴腭会形成暗色的腭舌气隙。"},{"en":"Incorrect biting primarily changes anterior positioning and magnification.","zh":"咬合位置错误主要影响前牙定位和放大率。"},{"en":"Holding the handles affects stability but does not create this characteristic band.","zh":"握住扶手影响稳定性，但不会产生这种特征性透射带。"},{"en":"Eyeglasses can create radiopaque artifacts, not a broad radiolucent band.","zh":"眼镜会产生不透射伪影，而不是宽大的透射带。"}],"level":"Board-style","pearl":"A dark band over maxillary apices usually means the tongue was not against the palate."},{"id":56,"concept":"Anatomy","stem":"Which radiographic landmark commonly appears as a U- or J-shaped radiopacity superior to the maxillary first molar region?","choices":["Zygomatic process of the maxilla","Mental foramen","Incisive foramen","Mandibular canal"],"answer":0,"why":"The zygomatic process of the maxilla typically appears as a U- or J-shaped radiopacity near the maxillary molars.","zh":"哪一放射解剖标志通常在上颌第一磨牙区上方呈U形或J形不透射影？","rationales":[{"en":"Correct: the zygomatic process is a characteristic U- or J-shaped radiopacity.","zh":"正确：上颌骨颧突常呈特征性的U形或J形不透射影。"},{"en":"The mental foramen is a mandibular radiolucency near the premolars.","zh":"颏孔是下颌前磨牙区附近的透射影。"},{"en":"The incisive foramen appears in the anterior maxilla near the central incisors.","zh":"切牙孔位于上颌前牙区中切牙附近。"},{"en":"The mandibular canal appears as a radiolucent band bordered by radiopaque lines in the mandible.","zh":"下颌管在下颌骨内呈由不透射线边界包绕的透射带。"}],"level":"Interpretation","pearl":"A U- or J-shaped radiopacity over maxillary molars is usually the zygomatic process."},{"id":57,"concept":"Interpretation","stem":"A round radiolucency near the apex of a mandibular second premolar is seen on a radiograph. The tooth is vital and asymptomatic. What is the MOST likely explanation?","choices":["Mental foramen superimposition","Periapical abscess","Radicular cyst","Internal resorption"],"answer":0,"why":"A vital asymptomatic premolar with a well-positioned radiolucency near the apex often reflects superimposition of the mental foramen.","zh":"在下颌第二前磨牙根尖附近见圆形透射影。该牙有活力且无症状。最可能的解释是什么？","rationales":[{"en":"Correct: the mental foramen commonly overlaps mandibular premolar apices and can mimic pathology.","zh":"正确：颏孔常与下颌前磨牙根尖重叠，可模拟病变。"},{"en":"A periapical abscess is usually associated with a nonvital tooth and clinical signs or symptoms.","zh":"根尖脓肿通常与无活力牙及临床症状有关。"},{"en":"A radicular cyst is generally associated with a nonvital tooth.","zh":"根尖囊肿通常与无活力牙有关。"},{"en":"Internal resorption occurs within the root canal space rather than as a separate apical radiolucency.","zh":"内吸收发生在根管腔内，而不是独立的根尖透射影。"}],"level":"Clinical","pearl":"Always correlate radiographic findings with vitality tests and clinical examination."},{"id":58,"concept":"Caries Interpretation","stem":"Which statement about cervical burnout is MOST accurate?","choices":["It can mimic root caries because of reduced x-ray absorption near the CEJ","It is always a true carious lesion","It appears only on panoramic images","It is caused by overdevelopment of film"],"answer":0,"why":"Cervical burnout is a radiographic artifact caused by relatively less dense anatomy near the CEJ and may resemble root caries.","zh":"关于颈部透亮影（cervical burnout），哪项陈述最准确？","rationales":[{"en":"Correct: cervical burnout can resemble root caries and must be correlated clinically.","zh":"正确：颈部透亮影可类似根面龋，必须结合临床检查。"},{"en":"It is an artifact, not automatically a carious lesion.","zh":"它是一种伪影，并不一定是真实龋病。"},{"en":"It can appear on intraoral images, especially bitewings and periapicals.","zh":"它可出现在口内影像中，尤其是咬翼片和根尖片。"},{"en":"Its cause is anatomic attenuation differences, not film overdevelopment.","zh":"其原因是解剖结构的吸收差异，而不是显影过度。"}],"level":"Interpretation","pearl":"Cervical burnout should be confirmed clinically before diagnosing root caries."},{"id":59,"concept":"Localization","stem":"Using the SLOB rule, a second radiograph is taken with the tube shifted mesially. The object image also moves mesially. Where is the object located?","choices":["Lingual","Buccal","Within the pulp chamber","The location cannot be determined"],"answer":0,"why":"SLOB means Same Lingual, Opposite Buccal. Movement in the same direction as the tube shift indicates a lingual location.","zh":"使用SLOB规则时，第二张影像将射线管向近中移动，物体影像也向近中移动。该物体位于何处？","rationales":[{"en":"Correct: same-direction movement indicates a lingual position.","zh":"正确：与射线管同方向移动表示位于舌侧。"},{"en":"A buccal object moves in the opposite direction from the tube shift.","zh":"颊侧物体会向与射线管移动相反的方向移动。"},{"en":"SLOB determines buccolingual location, not whether an object lies in the pulp chamber.","zh":"SLOB用于判断颊舌侧位置，而不是判断是否位于髓腔。"},{"en":"The location can be determined because both tube and object movement directions are known.","zh":"由于已知射线管和物体移动方向，因此可以判断位置。"}],"level":"Calculation","pearl":"SLOB: Same Lingual, Opposite Buccal."},{"id":60,"concept":"Quality Assurance","stem":"A digital image repeatedly appears grainy because too few x-ray photons reached the receptor. What is the MOST appropriate corrective action?","choices":["Increase exposure enough to obtain adequate receptor signal while remaining within ALARA","Decrease exposure further","Use image enhancement to replace proper exposure","Repeat every image automatically"],"answer":0,"why":"Quantum mottle results from insufficient receptor exposure; exposure should be increased only enough to achieve diagnostic quality while following ALARA.","zh":"数字影像反复呈颗粒状，因为到达感受器的X射线光子过少。最适当的纠正措施是什么？","rationales":[{"en":"Correct: increase exposure only to the level needed for diagnostic signal and continue using ALARA.","zh":"正确：仅将曝光提高到获得诊断信号所需的水平，并继续遵循ALARA原则。"},{"en":"Further reducing exposure would worsen quantum noise.","zh":"进一步降低曝光会加重量子噪声。"},{"en":"Post-processing cannot fully restore information that was never captured.","zh":"后处理无法完全恢复从未被采集到的信息。"},{"en":"Automatic repetition violates radiation-protection principles and ignores the cause.","zh":"自动重拍违反辐射防护原则，也未解决根本原因。"}],"level":"Clinical","pearl":"Digital systems can hide overexposure, but underexposure often appears as quantum noise or graininess."}];
window.FULL_BANK=RADIOLOGY_BANK;
